    cudaMallocManaged(&A, M * N * sizeof(float));
    cudaMallocManaged(&B, N * P * sizeof(float));
    cudaMallocManaged(&C, M * P * sizeof(float));

    // Initialize data
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
            A[i * N + j] = i + j;
        }
    }
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < P; j++) {
            B[i * P + j] = i + j;
        }
    }

    RAJA::forall<RAJA::cuda_exec<256, 256>>(RAJA::RangeSegment(0, M), RAJA::RangeSegment(0, P), [=] RAJA_HOST_DEVICE(int row, int col) {
        float sum = 0.0f;
        for (int i = 0; i < N; i++) {
            sum += A[row * N + i] * B[i * P + col];
        }
        C[row * P + col] = sum;
    });

    // Synchronize
    cudaDeviceSynchronize();

    // Print result
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < P; j++) {
            printf("%f ", C[i * P + j]);
        }
        printf("\n");
    }

