    // --- RAJA Memory Management ---
    // RAJA abstracts the device memory allocation.
    // We specify the backend (CUDA in this case).
    using namespace raja;

    // Create device memory buffers using the CUDA backend
    device_vector<float> d_A(N);
    device_vector<float> d_B(N);
    device_vector<float> d_C(N);

    // Copy Host to Device (RAJA handles the necessary calls)
    d_A.copy_from(h_A.data());
    d_B.copy_from(h_B.data());

    // --- RAJA Parallel Execution ---
    // Replace the explicit kernel launch with parallel_for
