## Example 2: Matrix Multiplication (Tiled/Blocked Operation)

Matrix multiplication is more complex because it requires managing 2D indexing and often benefits from tiling/blocking, which RAJA can help abstract.

### 1. Original CUDA Code (Conceptual)

A CUDA implementation would use 2D thread blocks, calculate global row/column indices, and perform the dot product.

### 2. RAJA Portable Code (Using `raja::parallel_for` over a 2D range)

For simplicity, we will use a flat 1D loop over the output elements, but the structure shows how RAJA handles the iteration space.

```c++
// raja_matrix_mult.cpp
#include <iostream>
#include <vector>
#include <raja/raja.hpp>

// Matrix dimensions
constexpr int M = 1024; // Rows of C (and A)
constexpr int K = 1024; // Columns of A (and Rows of B)
constexpr int N_cols = 1024; // Columns of C (and B)

// RAJA Kernel (Standard C++ function)
void matrixMultiplyKernel(const float* A, const float* B, float* C, int M, int K, int N_cols) {
    // In a real implementation, this loop would be parallelized by RAJA.
    // Here, we simulate the work done by the parallel loop.
    for (int i = 0; i < M; ++i) { // Row of C
        for (int j = 0; j < N_cols; ++j) { // Column of C
            float sum = 0.0f;
            for (int k = 0; k < K; ++k) { // Dot product dimension
                // A[i, k] * B[k, j]
                sum += A[i * K + k] * B[k * N_cols + j];
            }
            C[i * N_cols + j] = sum;
        }
    }
}

void run_raja_matrix_mult(
    const std::vector<float>& h_A, 
    const std::vector<float>& h_B, 
    std::vector<float>& h_C) 
{
    using namespace raja;

    // 1. Device Memory Allocation
    device_vector<float> d_A(M * K);
    device_vector<float> d_B(K * N_cols);
    device_vector<float> d_C(M * N_cols);

    // 2. Copy Host to Device
    d_A.copy_from(h_A.data());
    d_B.copy_from(h_B.data());

    // 3. RAJA Parallel Execution (Iterating over the output elements C[i, j])
    // We iterate over the total number of elements in C (M * N_cols)
    parallel_for(0, M * N_cols, [&](int flat_idx) {
        // Map the flat index back to 2D coordinates (i, j)
        int i = flat_idx / N_cols; // Row index
        int j = flat_idx % N_cols; // Column index

        float sum = 0.0f;
        // Perform the inner dot product loop (this loop is sequential per thread)
        for (int k = 0; k < K; ++k) {
            // Accessing A[i, k] and B[k, j] using flat indexing
            sum += d_A[i * K + k] * d_B[k * N_cols + j];
        }

        // Store result in C[i, j]
        d_C[flat_idx] = sum;
    });

    // 4. Copy Device to Host
    d_C.copy_to(h_C.data());
}

int main() {
    std::cout << "Running RAJA Matrix Multiplication (using CUDA backend)..." << std::endl;

    // Initialize dummy data (A, B, C)
    std::vector<float> h_A(M * K, 1.0f);
    std::vector<float> h_B(K * N_cols, 2.0f);
    std::vector<float> h_C(M * N_cols, 0.0f);

    // Run the RAJA version
    run_raja_matrix_mult(h_A, h_B, h_C);

    // Verification (Check C[0, 0] = Sum(1.0 * 2.0) = K * 2.0)
    float expected_val = (float)K * 2.0f;
    float actual_val = h_C[0];

    std::cout << "Result C[0, 0]: " << actual_val << " (Expected: " << expected_val << ")" << std::endl;

    return 0;
}
```

