## Example 1: Simple Vector Addition (Element-wise Operation)

This is the most straightforward conversion, demonstrating the replacement of a simple kernel launch with `raja::parallel_for`.

### 1. Original CUDA Code

```c++
// cuda_vector_add.cu
#include <cuda_runtime.h>
#include <iostream>

// CUDA Kernel
__global__ void vectorAddKernel(const float* A, const float* B, float* C, int N) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < N) {
        C[i] = A[i] + B[i];
    }
}

void run_cuda_vector_add(float* h_A, float* h_B, float* h_C, int N) {
    // 1. Allocate Device Memory
    float *d_A, *d_B, *d_C;
    cudaMalloc((void**)&d_A, N * sizeof(float));
    cudaMalloc((void**)&d_B, N * sizeof(float));
    cudaMalloc((void**)&d_C, N * sizeof(float));

    // 2. Copy Host to Device
    cudaMemcpy(d_A, h_A, N * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_B, h_B, N * sizeof(float), cudaMemcpyHostToDevice);

    // 3. Kernel Launch Configuration
    int threadsPerBlock = 256;
    int blocks = (N + threadsPerBlock - 1) / threadsPerBlock;

    // 4. Kernel Launch
    vectorAddKernel<<<blocks, threadsPerBlock>>>(d_A, d_B, d_C, N);
    cudaDeviceSynchronize();

    // 5. Copy Device to Host
    cudaMemcpy(h_C, d_C, N * sizeof(float), cudaMemcpyDeviceToHost);

    // 6. Cleanup
    cudaFree(d_A);
    cudaFree(d_B);
    cudaFree(d_C);
}
```

### 2. RAJA Portable Code

We use `raja::parallel_for` to handle the loop iteration and RAJA's memory management (or rely on the backend to manage the pointers).

```c++
// raja_vector_add.cpp
#include <iostream>
#include <vector>
#include <raja/raja.hpp>

// RAJA Kernel (This is now a standard C++ function)
void vectorAddKernel(const float* A, const float* B, float* C, int N) {
    // RAJA handles the loop structure; we just implement the body.
    // The loop variable 'i' is provided by the parallel_for construct.
    for (int i = 0; i < N; ++i) {
        C[i] = A[i] + B[i];
    }
}

void run_raja_vector_add(std::vector<float>& h_A, std::vector<float>& h_B, std::vector<float>& h_C, int N) {
    // --- RAJA Memory Management ---
    // RAJA abstracts the device memory allocation.
    // We specify the backend (CUDA in this case).
    using namespace raja;

    // Create device memory buffers using the CUDA backend
    device_vector<float> d_A(N);
    device_vector<float> d_B(N);
    device_vector<float> d_C(N);

    // Copy Host to Device (RAJA handles the necessary calls)
    d_A.copy_from(h_A.data());
    d_B.copy_from(h_B.data());

    // --- RAJA Parallel Execution ---
    // Replace the explicit kernel launch with parallel_for
    parallel_for(0, N, [&](int i) {
        // The lambda captures the necessary pointers/references
        // RAJA ensures that 'i' maps correctly to a thread/work item.
        d_C[i] = d_A[i] + d_B[i];
    });

    // Copy Device to Host
    d_C.copy_to(h_C.data());
}

int main() {
    const int N = 1024 * 1024;
    std::vector<float> h_A(N, 1.0f);
    std::vector<float> h_B(N, 2.0f);
    std::vector<float> h_C(N);

    std::cout << "Running RAJA Vector Addition (using CUDA backend)..." << std::endl;

    // Run the RAJA version
    run_raja_vector_add(h_A, h_B, h_C, N);

    // Verification (Check the first element)
    std::cout << "Result C[0]: " << h_C[0] << " (Expected: 3.0)" << std::endl;

    return 0;
}
```

